  ('iphone-16-pro', 'sku-ip16p-magsafe', 'magsafe', 'Trong suốt MagSafe', '#ECE6FD', 45),
  ('iphone-15-pro', 'sku-ip15p-lilac', 'tough', 'Tím Lilac', '#A58CF4', 60),
  ('iphone-15-pro', 'sku-ip15p-black', 'snap', 'Đen Jet Black', '#0A0A0A', 80),
  ('galaxy-s24', 'sku-s24-lilac', 'tough', 'Tím Lilac', '#A58CF4', 50),
