  ('accessory-astronaut-star', 'Charm phi hành gia', 'Charm phi hành gia và ngôi sao cho người mê vũ trụ.', 'accessory', '/products/Accessories/10_astronaut_star_charm.png', 'Charm', null)
on conflict (slug) do update
  set name = excluded.name, description = excluded.description, image_url = excluded.image_url,
      category = excluded.category, badge = excluded.badge, is_active = true;

insert into public.inventory_items (kind, name, phone_model_id, quantity_on_hand, sku_code)
select 'trade_good', 'Kho ' || a.name, null, a.qty, a.slug
from (values
  ('accessory-charging-puck', 'Đế sạc từ tính', 14),
  ('accessory-magnetic-wallet', 'Ví da từ tính', 18),
  ('accessory-ring-holder', 'Nhẫn giữ từ tính', 25),
  ('accessory-desk-stand', 'Giá đỡ để bàn từ tính', 9),
  ('accessory-power-bank', 'Pin dự phòng từ tính', 11),
  ('accessory-beaded-wristlet', 'Dây đeo hạt Lavender', 20),
  ('accessory-braided-strap', 'Dây đeo cổ tay bện', 22),
  ('accessory-flower-charm', 'Charm hoa acrylic', 30),
  ('accessory-plush-star', 'Charm ngôi sao bông', 16),
  ('accessory-astronaut-star', 'Charm phi hành gia', 0)
) a (slug, name, qty)
on conflict (sku_code) do nothing;

insert into public.product_variants (product_id, name, phone_model_id, inventory_item_id, price, color_sku, is_active)
select p.id, null, null, i.id, a.price, null, true
from (values
  ('accessory-charging-puck', 490000),
  ('accessory-magnetic-wallet', 390000),
  ('accessory-ring-holder', 190000),
  ('accessory-desk-stand', 450000),
  ('accessory-power-bank', 690000),
  ('accessory-beaded-wristlet', 150000),
  ('accessory-braided-strap', 120000),
  ('accessory-flower-charm', 89000),
  ('accessory-plush-star', 99000),
  ('accessory-astronaut-star', 119000)
) a (slug, price)
join public.products p on p.slug = a.slug
join public.inventory_items i on i.kind = 'trade_good' and i.sku_code = a.slug
on conflict (product_id, coalesce(phone_model_id::text, ''), coalesce(color_sku, '')) do update
  set inventory_item_id = excluded.inventory_item_id, price = excluded.price, is_active = true;

-- The three seed v1 accessories are not sold any more.
update public.products set is_active = false
where slug in ('accessory-magsafe', 'accessory-airpods', 'accessory-strap');
